/**
 * i18n (FRAMEWORK §6.3, §6.4; owner: scaffold). React-free.
 *
 * - `t(key, vars?, voice?)` reads /i18n/vi.json (generated by i18n/tools/build_vi.py; add keys there).
 * - Sender-voice keys (gift.*, create.share.message, create.message.suggest*) resolve the pronoun
 *   placeholders {self} {Self} {you} {You} {we} {We} {nha} from a `Voice`. Other placeholders come
 *   from `vars`. Every output and every interpolated value is NFC-normalised.
 * - Text helpers: `nfc`, `graphemes` (Intl.Segmenter 'vi' grapheme split), `words`, `graphemeCount`.
 * - Never upper/lower-case Vietnamese with CSS; use `upperVi` (toLocaleUpperCase('vi')) when a style
 *   needs caps (eyebrows) and never on names inside script faces.
 */
import strings from '@strings/vi.json';

export type Locale = 'vi' | 'en';
export type StringKey = keyof typeof strings.vi;
export type PronounSetId = keyof typeof strings.pronouns;
export type ToneId = keyof typeof strings.tone;
export type Vars = Readonly<Record<string, string | number>>;

/** Who speaks to whom in sender-voice strings. Either a pronoun set or explicit words (GiftContentV1.names). */
export interface Voice {
  /** Pronoun set from vi.json → pronouns (e.g. 'anh-em'). With `self`/`you` it still picks {we}/{We} and the
   *  tone override; when absent it is inferred from `self`/`you` (unknown words → 'none'). */
  readonly pronouns?: PronounSetId;
  /** Explicit words, e.g. from a gift: { self: 'anh', you: 'em' }. Capitalised forms are derived. */
  readonly self?: string;
  readonly you?: string;
  readonly we?: string;
  /** 'north' → "nhé", 'south' → "nha". GiftContentV1 stores 'nhe' | 'nha'; both spellings are accepted. */
  readonly tone?: ToneId | 'nhe' | 'nha';
  /** Used when the pronoun set is 'none' ("you" becomes the recipient's name). */
  readonly recipientName?: string;
}

const PRONOUN_PH = new Set(['self', 'Self', 'you', 'You', 'we', 'We', 'nha']);
const PH = /\{(\w+)\}/g;

let locale: Locale = 'vi';
export const setLocale = (l: Locale): void => { locale = l; };
export const getLocale = (): Locale => locale;

/** NFC-normalise (input from users, URLs and IMEs can arrive decomposed). */
export const nfc = (s: string): string => s.normalize('NFC');

const capFirst = (s: string): string => {
  const [first, ...rest] = graphemes(s);
  return first === undefined ? s : first.toLocaleUpperCase('vi') + rest.join('');
};

/** Resolve the pronoun placeholder values for a voice. */
/** A stored pronoun id (from a gift link) → a known set id, or undefined. */
export const pronounSetOf = (id: unknown): PronounSetId | undefined =>
  typeof id === 'string' && Object.prototype.hasOwnProperty.call(strings.pronouns, id) ? (id as PronounSetId) : undefined;

/** Which pronoun set a voice speaks in: explicit id, else matched from self/you, else 'anh-em' (no words) / 'none'. */
function setIdOf(voice: Voice): PronounSetId {
  if (voice.pronouns) return voice.pronouns;
  if (!voice.self && !voice.you) return 'anh-em';
  const self = nfc(voice.self ?? '').trim(), you = nfc(voice.you ?? '').trim();
  for (const [id, p] of Object.entries(strings.pronouns) as [PronounSetId, (typeof strings.pronouns)[PronounSetId]][]) {
    if (id !== 'none' && p.self === self && p.you === you) return id;
  }
  return 'none';
}

export function voiceWords(voice: Voice = {}): Record<string, string> {
  const setId = setIdOf(voice);
  const set = strings.pronouns[setId];
  const toneId: ToneId = voice.tone === 'nhe' ? 'north' : voice.tone === 'nha' ? 'south' : (voice.tone ?? 'south');
  const tone = strings.tone[toneId];
  const name = voice.recipientName ? nfc(voice.recipientName) : '';
  let we = voice.we ?? set.we;
  let We = voice.we ? capFirst(voice.we) : set.We;
  const ov = (tone.weOverride as Record<string, readonly [string, string] | undefined>)[setId];
  if (!voice.we && ov) { we = ov[0]; We = ov[1]; }
  const self = voice.self ? nfc(voice.self) : set.self;
  const you = voice.you ? nfc(voice.you) : set.you.replace('{recipientName}', name);
  return {
    self, Self: capFirst(self),
    you, You: voice.you ? capFirst(you) : set.You.replace('{recipientName}', name),
    we, We,
    nha: tone.nha,
  };
}

/**
 * Translate. Unknown keys return the key itself (and warn in dev) so a missing string is visible
 * rather than blank. Placeholders without a value are left as-is.
 */
export function t(key: StringKey, vars?: Vars, voice?: Voice): string {
  const table = strings[locale] as Record<string, string>;
  const raw = table[key] ?? (strings.vi as Record<string, string>)[key];
  if (raw === undefined) {
    if (import.meta.env?.DEV) console.warn(`[i18n] missing key ${String(key)}`);
    return String(key);
  }
  const pw = raw.includes('{') && [...raw.matchAll(PH)].some((m) => PRONOUN_PH.has(m[1] ?? '')) ? voiceWords(voice) : null;
  return nfc(raw.replace(PH, (whole, name: string) => {
    if (vars && name in vars) return nfc(String(vars[name]));
    if (pw && name in pw) return pw[name] ?? whole;
    return whole;
  }));
}

/** True when `key` exists in vi.json (for data-driven keys such as step params `{ key: 'booth.pill.smile' }`). */
export const hasKey = (key: string): key is StringKey => key in strings.vi;

// ---------------------------------------------------------------- graphemes
let gSeg: Intl.Segmenter | null = null;
let wSeg: Intl.Segmenter | null = null;

/** Split NFC text into user-perceived characters (P42 typewriter unit). "Nguyễn" → N g u y ễ n. */
export function graphemes(text: string): string[] {
  const s = nfc(text);
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    gSeg ??= new Intl.Segmenter('vi', { granularity: 'grapheme' });
    return Array.from(gSeg.segment(s), (x) => x.segment);
  }
  return Array.from(s); // code points; after NFC every Vietnamese letter is one code point
}

export const graphemeCount = (text: string): number => graphemes(text).length;

/**
 * Split into words and the whitespace between them, keeping both, so a renderer can wrap each
 * word in a `white-space: nowrap` span (§3.4 rule 7) and reveal per word above 130 graphemes.
 */
export function words(text: string): { text: string; space: boolean }[] {
  const s = nfc(text);
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    wSeg ??= new Intl.Segmenter('vi', { granularity: 'word' });
    const out: { text: string; space: boolean }[] = [];
    for (const seg of wSeg.segment(s)) {
      const space = /^\s+$/.test(seg.segment);
      const last = out[out.length - 1];
      // merge punctuation into the preceding word so "nha." never wraps alone
      if (!space && !seg.isWordLike && last && !last.space) last.text += seg.segment;
      else out.push({ text: seg.segment, space });
    }
    return out;
  }
  return s.split(/(\s+)/).filter(Boolean).map((w) => ({ text: w, space: /^\s+$/.test(w) }));
}

/** Locale-aware caps for eyebrows (never CSS text-transform on Vietnamese). */
export const upperVi = (s: string): string => nfc(s).toLocaleUpperCase('vi');

/**
 * Secret-answer comparison (§6.4, arch §6.3): NFC → lowercase vi → trim → collapse spaces.
 * The diacritic-free loose match is accepted only when the typed input had no diacritics.
 */
export function normaliseAnswer(s: string): string {
  return nfc(s).toLocaleLowerCase('vi').trim().replace(/\s+/g, ' ');
}
export function stripDiacritics(s: string): string {
  return nfc(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').normalize('NFC');
}
export function answerMatches(input: string, expected: string): boolean {
  const a = normaliseAnswer(input), b = normaliseAnswer(expected);
  if (a === b) return true;
  return stripDiacritics(a) === a && stripDiacritics(b) === a;
}
